        # 1. Decode Image
        try:
            if "base64," in image:
                image_data = base64.b64decode(image.split("base64,")[1])
            else:
                image_data = base64.b64decode(image)
                
            original_image = Image.open(io.BytesIO(image_data)).convert("RGB")
        except Exception as e:
            raise HTTPException(status_code=400, detail=f"Invalid image data: {str(e)}")

        # 2. Step 1: The "Identifier" (Masking)
        print(f"Step 1: Identifying target area for '{feature_name}'...")
        # Use simple fallback strategy which now includes the 'Nose Box' logic
        mask = identifier.get_mask(original_image, feature_name, strategy="auto", prompt=refinement_prompt)  # pyre-ignore[16]
        
        # 3. Post-Process Mask with surgical boundary enforcement
        processed_mask = identifier.process_mask(mask, feature_name=feature_name)  # pyre-ignore[16]

        # 4. Step 2: The "Surgeon" (Inpainting)
        print(f"Step 2: Performing refinement...")
        
        lower_prompt = refinement_prompt.lower()
        feature_lower = feature_name.lower()
        
        # --- LOGIC BRANCHES ---
        
        # We use the full contextual prompt correctly passed from the frontend
        full_prompt = updated_prompt if updated_prompt else refinement_prompt
        
        # Branch A: Surgical Nose Job
        if "nose" in feature_lower:
            print(">>> ACTIVATING SURGICAL NOSE JOB PIPELINE <<<")
            
            # Check if user selected one of our preset styles
