@app.post("/api/search-database")
async def search_database(image: str = Form(...)):
    try:
        if encoder is None or db is None:
             raise HTTPException(status_code=503, detail="Search service unavailable")

        try:
            if "base64," in image:
                image_data = base64.b64decode(image.split("base64,")[1])
            else:
                image_data = base64.b64decode(image)
            original_image = Image.open(io.BytesIO(image_data)).convert("RGB")
        except Exception as e:
            raise HTTPException(status_code=400, detail="Invalid image data")

        vector = encoder.encode(original_image)  # pyre-ignore[16]
        print(f"Generated vector for search. Querying database...")
        
        matches = db.search(vector, top_n=6)  # pyre-ignore[16]
        
        return {
            "matches": matches
        }
            
    except Exception as e:
        print(f"Search Error: {e}")
        import traceback
        traceback.print_exc()
        raise HTTPException(status_code=500, detail=f"Search failed: {str(e)}")

@app.post("/api/tts")
async def text_to_speech(text: str = Form(...)):
    print(f"TTS Request: {text}")
    try:
        ELEVENLABS_API_KEY = os.getenv("ELEVENLABS_API_KEY")
        if not ELEVENLABS_API_KEY:
             print("Warning: ELEVENLABS_API_KEY not set. Returning silently to avoid errors.")
             return {"audio": ""}

        url = "https://api.elevenlabs.io/v1/text-to-speech/nPczCjzI2devNBz1zQrb" # Declan ID (or similar deep voice)
        
        headers = {
            "Accept": "audio/mpeg",
            "Content-Type": "application/json",
            "xi-api-key": ELEVENLABS_API_KEY  # pyre-ignore[6]
        }
        
        data = {
            "text": text,
            "model_id": "eleven_multilingual_v2",
            "voice_settings": {
                "stability": 0.5,
                "similarity_boost": 0.75
            }
        }

        import requests  # pyre-ignore[21]
        response = requests.post(url, json=data, headers=headers)
        
        if response.status_code != 200:
            print(f"ElevenLabs Error: {response.text}")
            raise HTTPException(status_code=response.status_code, detail="TTS generation failed")

        # Encode audio to base64 to send back JSON (or stream binary)
        # For simplicity with current setup, let's return base64
        audio_base64 = base64.b64encode(response.content).decode('utf-8')
        
        return {"audio": f"data:audio/mpeg;base64,{audio_base64}"}

    except Exception as e:
        print(f"TTS Error: {e}")
        raise HTTPException(status_code=500, detail=str(e))

if __name__ == "__main__":
    import uvicorn  # pyre-ignore[21]
    uvicorn.run(app, host="0.0.0.0", port=8000)

